package com.hn26.zaradniaki.zusbaby.golden;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.List;
import java.util.stream.Stream;

import tools.jackson.databind.JavaType;
import tools.jackson.databind.json.JsonMapper;

/**
 * Loads golden cases from {@code src/test/resources/golden/<area>.json},
 * generated by {@code tools/golden/generate.mjs} from the frontend prototype.
 * Use as a {@code @MethodSource}:
 *
 * <pre>
 * static Stream&lt;GoldenCase&lt;Input, Expected&gt;&gt; cases() {
 *     return GoldenCases.load("deadlines", Input.class, Expected.class);
 * }
 * </pre>
 */
public final class GoldenCases {

    private static final JsonMapper JSON = JsonMapper.builder().build();

    private GoldenCases() {
    }

    public static <I, E> Stream<GoldenCase<I, E>> load(String area, Class<I> inputType, Class<E> expectedType) {
        JavaType caseType = JSON.getTypeFactory().constructParametricType(GoldenCase.class, inputType, expectedType);
        JavaType fileType = JSON.getTypeFactory().constructParametricType(GoldenFile.class, caseType);
        String resource = "/golden/" + area + ".json";
        try (InputStream in = GoldenCases.class.getResourceAsStream(resource)) {
            if (in == null) {
                throw new IllegalStateException(
                        resource + " not found; run: node tools/golden/generate.mjs <path-to-mockup>");
            }
            GoldenFile<GoldenCase<I, E>> file = JSON.readValue(in, fileType);
            if (file.cases() == null || file.cases().isEmpty()) {
                throw new IllegalStateException(resource + " has no cases");
            }
            return file.cases().stream();
        } catch (IOException ex) {
            throw new UncheckedIOException(ex);
        }
    }

    /** File layout: where the cases come from and the cases themselves. */
    record GoldenFile<C>(String source, List<C> cases) {
    }
}
